package com.example.starter.arbitration.domain;

/**
 * 资源写权限租约行（t_lease）。任一资源同一时刻至多一条 active=1 的租约。
 */
public class LeasePo {

    /** 自增主键。 */
    private Long id;
    /** 持有方控制器标识。 */
    private String controllerId;
    /** 被占有的资源名。 */
