@Transactional
public LeaseResponse release(ReleaseLeaseRequest request) {
    List<LeasePo> all = leaseRepository.findAllActive().stream()
            .filter(l -> l.getControllerId().equals(request.controllerId())
                    && l.getRequestId().equals(request.requestId()))
            .toList();
    // 历史上是否存在过该申请（从未见过则 404）
    boolean everExisted = !leaseRepository.findAllActive().isEmpty()
            || !resourcesOfHistoricalRequest(request.controllerId(), request.requestId()).isEmpty();
    List<String> resources = new ArrayList<>();
    long expiredAt = 0L;
    for (LeasePo lease : all) {
        if (leaseRepository.deactivateIfActive(lease.getId(), "RELEASED") > 0) {
            activeClaimRepository.deleteByLeaseId(lease.getId());
        }
        resources.add(lease.getResourceName());
        expiredAt = lease.getExpiresAtMs();
    }
    if (all.isEmpty()) {
        List<String> historical = resourcesOfHistoricalRequest(
                request.controllerId(), request.requestId());
        if (historical.isEmpty()) {
            throw ApiException.notFound("LEASE_NOT_FOUND",
                    "控制器 " + request.controllerId() + 的申请 " + request.requestId() + " 不存在");
        }
        // 已释放/失效后的重复释放：幂等成功
        return new LeaseResponse(false, request.controllerId(), request.requestId(), historical,
                0, 0L, 0L, false, List.of(), true);
    }
    return new LeaseResponse(false, request.controllerId(), request.requestId(), resources,
            all.get(0).getPriority(), all.get(0).getAcquiredAtMs(), expiredAt,
            false, List.of(), false);
}

