        throw ApiException.conflict("REQUEST_ID_PARAM_MISMATCH",
                "requestId " + request.requestId() + " 已用于 TTL=" + oldTtl
                        + "ms 的申请，本次 TTL=" + requestedTtl + "ms 为异参重放");
