        mockMvc.perform(post("/api/arbitration/commands")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"controllerId\":\"ctrl_low\",\"requestId\":\"cmd-bad\","
                                + "\"resourceName\":\"joint_a\",\"timestampMs\":" + (clock.now() + 200)
